reg[9:0] h3,l3;
initial $readmemh("shared_font_index_bank3.hex",bank3);
always @(posedge clk_hdmi) h3<=bank3[addr_hdmi[9:0]];
always @(posedge clk_lvds) l3<=bank3[addr_lvds[9:0]];
(* ram_style="block" *) reg[9:0] bank4[0:1023];
reg[9:0] h4,l4;
initial $readmemh("shared_font_index_bank4.hex",bank4);
always @(posedge clk_hdmi) h4<=bank4[addr_hdmi[9:0]];
always @(posedge clk_lvds) l4<=bank4[addr_lvds[9:0]];
always @* begin
 hlow=0;
 case(hbank)
  3'd0: hlow=h0;
  3'd1: hlow=h1;
  3'd2: hlow=h2;
  3'd3: hlow=h3;
  3'd4: hlow=h4;
  default: ;
 endcase
 bits_hdmi=decode_row({hhigh,hlow});
end
always @* begin
 llow=0;
 case(lbank)
  3'd0: llow=l0;
  3'd1: llow=l1;
  3'd2: llow=l2;
  3'd3: llow=l3;
  3'd4: llow=l4;
  default: ;
 endcase
 bits_lvds=decode_row({lhigh,llow});
end
endmodule
